--- load.go ---
// Package conf merges configuration from file contents and the
// environment.
package conf

import "strings"

// Load merges a config file's content with environment overrides.
//
// fileContent is parsed as key=value lines. environ entries whose key
// starts with "APP_" have that prefix stripped and override the file
// values for the same key. Matching between an environment-derived key
// and an existing file key is case-insensitive so that, e.g., APP_TIMEOUT
// overrides a file entry named "timeout". When no existing key matches,
// the derived key (with its original case, after prefix removal) is
// used as-is.
func Load(fileContent string, environ []string) map[string]string {
	out := parseFile(fileContent)

	// Build a lookup from lower-cased key to the actual key stored in
	// out, so we can match case-insensitively against file keys.
	lookup := make(map[string]string, len(out))
	for k := range out {
		lookup[strings.ToLower(k)] = k
	}

	for _, entry := range environ {
		i := strings.Index(entry, "=")
		if i < 0 {
			continue
		}
		key := entry[:i]
		val := entry[i+1:]
		if !strings.HasPrefix(key, "APP_") {
			continue
		}
		key = strings.TrimPrefix(key, "APP_")

		lowerKey := strings.ToLower(key)
		if existing, ok := lookup[lowerKey]; ok {
			out[existing] = val
		} else {
			out[key] = val
			lookup[lowerKey] = key
		}
	}

	return out
}


--- parse.go ---
package conf

import "strings"

// parseFile parses key=value lines. Empty lines and comments (lines
// starting with '#') are ignored. Only the first '=' splits the pair.
func parseFile(content string) map[string]string {
	out := map[string]string{}
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		i := strings.Index(line, "=")
		if i < 0 {
			continue
		}
		key := strings.TrimSpace(line[:i])
		val := strings.TrimSpace(line[i+1:])
		out[key] = val
	}
	return out
}

