package slug

import (
	"strings"
	"unicode"
)

// Slugify converts arbitrary text into a URL slug following the specified rules.
func Slugify(s string) string {
	var b strings.Builder
	b.Grow(len(s))

	prevSep := false

	for _, r := range s {
		// Drop non-ASCII runes entirely.
		if r >= 0x80 {
			continue
		}

		// ASCII letters: lowercase and keep.
		if r >= 'A' && r <= 'Z' {
			r = r + ('a' - 'A')
			b.WriteRune(r)
			prevSep = false
			continue
		}
		if r >= 'a' && r <= 'z' {
